return ['x-generator'=>'GlotPress/4.0.1','translation-revision-date'=>'2023-02-14 12:44:29+0000','plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n >= 2 && n <= 4) ? 1 : 2);','project-id-version'=>'Plugins - Password Protected – Password Protect your WordPress Site, Pages, &amp; WooCommerce Products &#8211; Restrict Content, Protect WooCommerce Category, and more - Stable (latest release)','language'=>'cs_CZ','messages'=>['https://translate.wordpress.org/projects/wp-plugins/password-protected'=>'https://translate.wordpress.org/locale/cs/default/wp-plugins/password-protected','W3 Total Cache'=>'W3 Total Cache','Feeds are not available for this site. Please visit the <a href="%s">website</a>.'=>'Kanály nejsou k dispozici pro tento web. Navšivte prosím <a href="%s">web</a>.','Incorrect Password'=>'Neplatné heslo','Password Protected'=>'Password Protected','Password Protected Settings'=>'Password Protected Nastavení','Save Changes'=>'Uložit změny','<p><strong>Password Protected Status</strong><br />Turn on/off password protection.</p>'=>'<p><strong>Status Password Protected</strong><br>Zapnout/vypnout ochranu heslem.</p>','<p><strong>Password Fields</strong><br />To set a new password, enter it into both fields. You cannot set an `empty` password. To disable password protection uncheck the Enabled checkbox.</p>'=>'<p><strong>Pole hesel</strong> <br /> Chcete-li nastavit nové heslo, zadejte ho do obou polí. Nelze nastavit `prázdné` heslo. Chcete-li zrušit ochranu heslem odškrtněte políčko Zapnuto. </p>','Password Protected Status'=>'Password Protected Status','Protected Permissions'=>'Password Protected Oprávnění','New Password'=>'Nové heslo','New password not saved. When setting a new password please enter it in both fields.'=>'Nové heslo není uložen. Při nastavení nového hesla jej zadejte v obou oblastech.','New password not saved. Password fields did not match.'=>'Nové heslo nebylo uloženo. Hesla se neshodují.','New password saved.'=>'Nové heslo uloženo.','Password protect your web site. Users will be asked to enter a password to view the site.'=>'Heslo chrání vaše webové stránky. Uživatelé budou požádáni o zadání hesla pro zobrazení webu.','For more information about Password Protected settings, view the "Help" tab at the top of this page.'=>'Pro více informací o nastavení Password Protected, přejděte na záložku "Nápověda" v horní liště.','Enabled'=>'Povoleno','Allow Administrators'=>'Povolit správce','Allow Logged In Users'=>'Povolit přihlášené uživatele','Allow RSS Feeds'=>'Povolit informační kanál RSS','If you would like to change the password, type a new one. Otherwise, leave this blank.'=>'Pokud si chcete změnit současné heslo, zadejte nové. Jinak nechte toto pole prázdné.','Type your new password again.'=>'Zadejte ještě jednou vaše nové heslo.','http://github.com/benhuson/password-protected'=>'http://github.com/benhuson/password-protected','GitHub'=>'GitHub','Translate'=>'Přeložit','Settings'=>'Nastavení','You have enabled password protection but not yet set a password. Please set one below.'=>'Povolili jste ochranu heslem, ale ještě jste nenastavili heslo. Prosím nastavte níže heslo.','You have enabled password protection and allowed administrators and logged in users - other users will still need to enter a password to view the site.'=>'Povolili jste ochranu heslem a povolili jste administrátorům a přihlášeným uživatelům - ostatní uživatelé stále budou muset zadat heslo pro zobrazení stránky.','You have enabled password protection and allowed administrators - other users will still need to enter a password to view the site.'=>'Povolili jste ochranu heslem a povolili jste administrátorům - ostatní uživatelé stále budou muset zadat heslo pro zobrazení stránky.','You have enabled password protection and allowed logged in users - other users will still need to enter a password to view the site.'=>'Povolili jste ochranu heslem a povolili jste přihlášeným uživatelům - ostatní uživatelé stále budou muset zadat heslo pro zobrazení stránky.','<strong>ERROR</strong>: Cookies are blocked or not supported by your browser. You must <a href=\'http://www.google.com/cookies.html\'>enable cookies</a> to use WordPress.'=>'<strong>CHYBA</strong>: Váš internetový prohlížeč buď nepodporuje cookies, nebo jsou přímo zakázány. Pro bezproblémové používání WordPressu musíte mít <a href=\'http://www.google.com/cookies.html\'>cookies povoleny</a>.','Password'=>'Heslo','Enter one IP address per line.'=>'Zadejte každou IP adresu na nový řádek.','https://wordpress.org/plugins/password-protected/'=>'https://cs.wordpress.org/plugins/password-protected/','Logout'=>'Odhlášení ','Log In'=>'Přihlášení','Remember Me'=>'Zapamatuj si mě','Allow IP Addresses'=>'Povolit IP adresy','<p><strong>Protected Permissions</strong><br />Allow access for logged in users and administrators without needing to enter a password. You will need to enable this option if you want administrators to be able to preview the site in the Theme Customizer. Also allow RSS Feeds to be accessed when the site is password protected.</p>'=>'<p><strong>Chráněné oprávnění</strong><br />Povolte přístup pro přihlášené uživatele a správce bez nutnosti zadání hesla. Budete muset povolit tuto možnost, pokud chcete, aby správci mohli zobrazit náhled stránky v úpravách šablony. Taktéž umožňuje přijímat informační kanály RSS, když je web chráněn heslem.</p>','A very simple way to quickly password protect your WordPress site with a single password. Please note: This plugin does not restrict access to uploaded files and images and does not work with some caching setups.'=>'Velice jednoduchý způsob, jak chránit heslem WordPress stránky. Plugin neomezuje přístup k nahraným souborů a nefunguje s WP Engine a s některými cache pluginy.']];